import{z as m,x as B,o as e,c as n,q as r,j as o,D as t,d as E,s as i,S as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"梯度累积与微批","description":"","frontmatter":{"title":"梯度累积与微批","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/grad-accum-microbatch.md","filePath":"llm/grad-accum-microbatch.md","lastUpdated":1791413859000}'),p={name:"llm/grad-accum-microbatch.md"};function h(c,a,d,A,_,b){const l=B("Mermaid");return e(),n("div",null,[a[2]||(a[2]=r('<h1 id="梯度累积与微批" tabindex="-1">梯度累积与微批 <a class="header-anchor" href="#梯度累积与微批" aria-label="Permalink to &quot;梯度累积与微批&quot;">​</a></h1><div class="epigraph"><p>优化器看见的 batch 是微批体积乘累积步数乘数据并行度；显存放不下时，用多次前反向的梯度加总来模拟大 batch，而不把学习率公式里的 $B$ 偷偷改掉。</p><footer>—— 对照 Goyal 等大 batch SGD；GPipe 的微批；预训练配方中的 global batch</footer></div><p><a href="/llm/ulysses-sp">上一课</a>按序列切分之后，单次前向的激活仍可能撑满卡：长 \\(s\\)、厚层、MoE 容量。不能再加大每卡微批，有时还要减小。本课不重讲 SP 布局。缺口是把「微批 / 累积 / 全局 batch / 学习率」收成一张会计，避免流水的 \\(M\\)、DP 的 \\(n\\)、累积的 \\(k\\) 被三个配置文件各写各的。MoE 的 All-to-All 会按微批触发；本课先把稠密情形的 \\(B\\) 钉住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记每卡微批 token 数为 \\(b_{\\mathrm{micro}}\\)（或样本数 × 长度），数据并行度 \\(n_{\\mathrm{dp}}\\)，累积步 \\(k\\)，则全局 batch \\(B=b_{\\mathrm{micro}}\\cdot n_{\\mathrm{dp}}\\cdot k\\)（再乘流水里同时注入的微批语义——必须与框架定义一致）。GPipe 的 \\(M\\) 往往就是这里的「一次优化步里流水线上飞过的微批数」，与 \\(k\\) 可能重合或相乘，取决于实现是否在流水 flush 之后才累积。配错则真实 \\(B\\) 与日志不一致，Chinchilla 会计、学习率标度全部错。</p><p><span class="marginnote">数字实例：每卡微批 4096 token、8 卡数据并行、累积 4 步，则全局 batch \\(B = 4096 \\times 8 \\times 4 = 131072\\) token。这三个数写在哪份配置里都行，但只要乘错一个——比如把 \\(k\\) 漏掉——学习率标度和数据配比的账就全错位了。</span></p><p>Goyal 等人指出大 batch 要线性放大学习率并做 warmup。预训练若靠累积把 \\(B\\) 做大，应沿用同一逻辑；若累积只是为了显存、意图保持小 \\(B\\)，就不要再乘学习率。意图必须声明。</p><h3 id="流水与累积的两种接法" tabindex="-1">流水与累积的两种接法 <a class="header-anchor" href="#流水与累积的两种接法" aria-label="Permalink to &quot;流水与累积的两种接法&quot;">​</a></h3><p>一种：一次 1F1B flush 消耗 \\(M\\) 个微批，立刻 step，则 \\(k=1\\)，\\(M\\) 参与 \\(B\\)。另一种：多次 flush 才 step，梯度在优化器里加总，则 \\(k\\gt 1\\)。ZB 与 DualPipe 的全局 batch 边界必须落在 step 上，不能落在半截双流上。</p><p><span class="marginnote">Norm 层与 Dropout 的统计应对「逻辑微批」还是「累积后」？训练里通常按微批算 BN 类统计；Transformer 多用 LN，问题较轻，但仍不要在累积之间更新 LN 的可学习参数以外的状态。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在一张表里写：\\(s\\)、\\(b_{\\mathrm{micro}}\\)、\\(M\\)、\\(k\\)、\\(n_{\\mathrm{dp}}\\)、\\(n_{\\mathrm{tp}}\\)、\\(n_{\\mathrm{pp}}\\)、\\(n_{\\mathrm{sp}}\\)，以及推导出的 \\(B\\) 与每步 token。加载器按 \\(b_{\\mathrm{micro}}\\) 吐数据；SP 对齐 padding 在这一层做完。改变任一并行度时重算 \\(B\\)，决定是改 \\(k\\) 保 \\(B\\) 还是改学习率跟新 \\(B\\)。</p><p>显存不够：先降 \\(b_{\\mathrm{micro}}\\)、开重计算，再加 \\(k\\) 保 \\(B\\)。\\(b_{\\mathrm{micro}}\\) 过小会伤害 GEMM 与拉低重叠率，这是计算通信课的约束。长 \\(s\\) 时优先降 \\(b_{\\mathrm{micro}}\\) 而不是降 \\(s\\)，以免违背长文档上采样。</p><p><span class="marginnote">重计算（激活检查点）翻译一下就是「显存换时间」：前向时不保存中间激活，反向需要时重新算一遍。代价是大约多一次前向的计算量，换来激活显存大幅下降——微批降不下去时，它通常是第一根救命稻草。</span></p>',14)),(e(),o(s,null,{default:t(()=>[i(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20OOM%5B%22%E6%98%BE%E5%AD%98%E5%90%83%E7%B4%A7%20%2F%20OOM%22%5D%20--%3E%20S1%5B%22%E5%85%88%E9%99%8D%20b_micro%22%5D%0A%20%20S1%20--%3E%20RC%5B%22%E5%BC%80%E6%BF%80%E6%B4%BB%E9%87%8D%E8%AE%A1%E7%AE%97%22%5D%0A%20%20RC%20--%3E%20K%7B%22%E7%9B%AE%E6%A0%87%20B%20%E8%BF%98%E4%BF%9D%E5%BE%97%E4%BD%8F%E5%90%97%3F%22%7D%0A%20%20K%20--%3E%7C%22%E5%81%8F%E5%B0%8F%22%7C%20ADDK%5B%22%E5%8A%A0%E7%B4%AF%E7%A7%AF%E6%AD%A5%20k%20%E4%BF%9D%20B%22%5D%0A%20%20K%20--%3E%7C%22%E5%B7%B2%E8%BE%BE%E6%A0%87%22%7C%20LR%7B%22%E5%AD%A6%E4%B9%A0%E7%8E%87%E8%B7%9F%E4%B8%8D%E8%B7%9F%20B%3F%22%7D%0A%20%20ADDK%20--%3E%20LR%0A%20%20LR%20--%3E%7C%22%E8%B7%9F%22%7C%20SCALE%5B%22%E6%8C%89%E5%A4%A7%20batch%20%E9%80%BB%E8%BE%91%E6%94%BE%E5%A4%A7%20%2B%20warmup%22%5D%0A%20%20LR%20--%3E%7C%22%E4%B8%8D%E8%B7%9F%22%7C%20KEEP%5B%22%E7%BB%B4%E6%8C%81%E5%B0%8F%20B%20%E4%B8%8E%E5%8E%9F%E5%AD%A6%E4%B9%A0%E7%8E%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h3 id="与退火、课程" tabindex="-1">与退火、课程 <a class="header-anchor" href="#与退火、课程" aria-label="Permalink to &quot;与退火、课程&quot;">​</a></h3><p>退火若改变平均 \\(s\\)，同样 \\(b_{\\mathrm{micro}}\\) 的激活跳动，可能要动态 \\(k\\)。动态 \\(k\\) 等于动态 \\(B\\)，学习率要跟。课程课说顺序与 LR 同表；本课要求 \\(B\\) 也在那张表上。</p><p><span class="marginnote">日志打印的 <code>tokens/sec</code> 必须声明是不是含 padding、是不是全局。SP padding 会让有效 token 小于 \\(B\\)。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>梯度累积是线性的：\\(\\sum_{i=1}^{k}g_i\\) 在全精度加总时等价于大 batch 的梯度（忽略 BN 与 Dropout 的噪声差异）。半精度累积要用 FP32 master 梯度，否则尾数被吃掉。流水的 \\(M\\) 个微批在一次 flush 内已经是一种「空间上的累积」，再在时间上累积 \\(k\\) 次，数值上都是求和，但同步点不同：flush 内有阶段间依赖，flush 间是完整的前反向。</p><p><span class="marginnote">常见误区：初学者容易把累积 4 步当成「连续做了 4 次独立的小更新」。实际上每个微批的梯度先累进 FP32 缓冲、第 \\(k\\) 个微批算完才一起更新权重——它模拟的是一次大 batch 的梯度，权重中途一步都没动。</span></p>',6)),(e(),o(s,null,{default:t(()=>[i(l,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20MIC%5B%22%E5%BE%AE%E6%89%B9%20b_micro%22%5D%20--%3E%20PP%5B%22%E6%B5%81%E6%B0%B4%20M%20%2F%201F1B%22%5D%0A%20%20PP%20--%3E%20ACC%5B%22%E7%B4%AF%E7%A7%AF%20k%20%E6%AC%A1%22%5D%0A%20%20ACC%20--%3E%20DP%5B%22DP%20%E5%B9%B3%E5%9D%87%22%5D%0A%20%20DP%20--%3E%20OPT%5B%22%E4%BC%98%E5%8C%96%E5%99%A8%20step%EF%BC%8C%E5%85%A8%E5%B1%80%20B%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>累积不减少 SP/TP 通信次数，只减少 step 次数，优化器与检查点更稀。过稀的 step 让学习率日程的「步」与墙钟脱节。下一课 MoE 的 All-to-All 每个微批都打一次，降 \\(b_{\\mathrm{micro}}\\)、加 \\(k\\) 会让通信次数线性涨，稠密模型上「用累积换显存」的经验不能照搬。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲 Ulysses；只补 \\(B\\) 的会计：微批、累积、DP、流水 \\(M\\)。</li><li>显存不够时降微批、加重计算、加 \\(k\\) 保 \\(B\\)；声明学习率跟不跟 \\(B\\)。</li><li>半精度要用 FP32 累积梯度。</li><li>MoE 下累积会放大 All-to-All 次数，下一课处理。</li><li>出处：Goyal et al., <em>Accurate, Large Minibatch SGD</em>；Huang et al., GPipe；Megatron-LM 配方中的 global batch 定义。</li></ul>',4))])}const P=m(p,[["render",h]]);export{D as __pageData,P as default};
